
(()=>{
 'use strict';
 const FOOTSTEP_B64='';
 let footBuffer=null,footLoading=null,footCursor=0;
 function decodeFootsteps(){
  if(footBuffer||footLoading||!audio?.ctx)return footLoading;
  try{const raw=atob(FOOTSTEP_B64),u8=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)u8[i]=raw.charCodeAt(i);footLoading=audio.ctx.decodeAudioData(u8.buffer.slice(0)).then(b=>footBuffer=b).catch(()=>null).finally(()=>footLoading=null);}catch(_e){}
  return footLoading;
 }
 const audioInitBase=audio.init.bind(audio);audio.init=function(){const r=audioInitBase();decodeFootsteps();return r;};
 const syntheticStep=audio.step.bind(audio);
 audio.step=function(running){
  if(settings.muted||!audio.ctx||audio.ctx.state!=='running')return;
  if(!footBuffer){decodeFootsteps();return syntheticStep(running);}
  const src=audio.ctx.createBufferSource(),gain=audio.ctx.createGain(),filter=audio.ctx.createBiquadFilter();
  src.buffer=footBuffer;filter.type='lowpass';filter.frequency.value=running?5200:4300;
  const t=audio.ctx.currentTime;gain.gain.setValueAtTime(running?.46:.34,t);gain.gain.exponentialRampToValueAtTime(.0001,t+(running?.30:.36));
  src.connect(filter);filter.connect(gain);gain.connect(audio.master);
  const usable=Math.max(.5,footBuffer.duration-.45);footCursor=(footCursor+(running?.43:.58))%usable;
  src.start(t,footCursor,running?.31:.37);src.stop(t+(running?.32:.38));
 };
})();
